export const x_defaultExtensionVersion = "0.1.0";

interface ProvisionalSessionRecord
{
  rootDirectory: string;
  model: ModelReference;
  createdAt: string;
}

const x_sequenceLocks = new Map<string, Promise<void>>();

function SessionKey(pile: string, sessionId: string): string
{
  return `${pile}\u0000${sessionId}`;
}

async function WithSessionLock<T>(
  pile: string,
  sessionId: string,
  operation: () => Promise<T>,
): Promise<T>
{
  const key = SessionKey(pile, sessionId);
  const previous = x_sequenceLocks.get(key) ?? Promise.resolve();
  let release!: () => void;
  const current = new Promise<void>((resolve) =>
  {
    release = resolve;
  });
  const tail = previous.then(() => current);
  x_sequenceLocks.set(key, tail);

  await previous;

  try
  {
    return await operation();
  }
  finally
  {
    release();
    if (x_sequenceLocks.get(key) === tail)
    {
      x_sequenceLocks.delete(key);
    }
  }
}

function ParseSessionLogEntry(line: string): SessionLogEntry | null
{
  const trimmed = line.trim();

  if (trimmed.length === 0)
  {
    return null;
  }

  try
  {
    return JSON.parse(trimmed) as SessionLogEntry;
  }
  catch
  {
    return null;
  }
}

export async function ReadAllSessionLogEntries(
  paths: StoragePaths,
  pile: string,
  sessionId: string,
): Promise<SessionLogEntry[]>
{
  const historyPath = ResolveHistoryFilePath(paths, pile, sessionId);

  let raw: string;

  try
  {
    raw = await readFile(historyPath, "utf8");
  }
  catch
  {
    return [];
  }

  const entries: SessionLogEntry[] = [];

  for (const line of raw.split("\n"))
  {
    const entry = ParseSessionLogEntry(line);

    if (entry !== null)
    {
      entries.push(entry);
    }
  }

  entries.sort((left, right) => left.sequence - right.sequence);
  return entries;
}

export async function ReadLatestSequence(
  paths: StoragePaths,
  pile: string,
  sessionId: string,
): Promise<number>
{
  const entries = await ReadAllSessionLogEntries(paths, pile, sessionId);

  if (entries.length === 0)
  {
    return 0;
  }

  return entries[entries.length - 1].sequence;
}

async function StreamSessionLogEntries(
  historyPath: string,
  onEntry: (entry: SessionLogEntry) => void | Promise<void>,
): Promise<void>
{
  try
  {
    await access(historyPath);
  }
  catch
  {
    return;
  }

  const stream = createReadStream(historyPath, { encoding: "utf8" });
  const lineReader = readline.createInterface({
    input: stream,
    crlfDelay: Infinity,
  });

  try
  {
    for await (const line of lineReader)
    {
      const entry = ParseSessionLogEntry(line);

      if (entry !== null)
      {
        await onEntry(entry);
      }
    }
  }
  finally
  {
    lineReader.close();
    stream.destroy();
  }
}

export async function AllocateSessionShell(
  paths: StoragePaths,
  pile: string,
  rootDirectory: string,
  model: ModelReference,
): Promise<AllocatedSessionShell>
{
  await EnsurePileExists(paths, pile);
  const sessionId = ValidateSessionId(randomUUID().replace(/-/g, ""));
  const absoluteRoot = ResolveRootDirectory(paths.repoRoot, rootDirectory);
  const sessionFilePath = ResolveSessionFilePath(paths, pile, sessionId);
  const historyFilePath = ResolveHistoryFilePath(paths, pile, sessionId);
  const provisionalFilePath = ResolveProvisionalFilePath(paths, pile, sessionId);
  const provisionalRecord: ProvisionalSessionRecord = {
    rootDirectory: absoluteRoot,
    model,
    createdAt: new Date().toISOString(),
  };

  await writeFile(sessionFilePath, "", "utf8");
  await writeFile(historyFilePath, "", "utf8");
  await writeFile(
    provisionalFilePath,
    `${JSON.stringify(provisionalRecord, null, 2)}\n`,
    "utf8",
  );

  return {
    pile,
    sessionId,
    provisionalSession: {
      rootDirectory: absoluteRoot,
      model,
    },
    sessionFilePath,
    historyFilePath,
  };
}

export interface AppendEnvelopeInput extends Omit<CreateChatEnvelopeInput, "sequence">
{
  sequence?: number;
}

export async function AppendEnvelope(
  paths: StoragePaths,
  pile: string,
  sessionId: string,
  input: AppendEnvelopeInput,
): Promise<ChatEnvelope>
{
  const validatedSessionId = ValidateSessionId(sessionId);

  return WithSessionLock(pile, validatedSessionId, async () =>
  {
    const historyPath = ResolveHistoryFilePath(paths, pile, validatedSessionId);
    const latestSequence = await ReadLatestSequence(paths, pile, validatedSessionId);
    const sequence = input.sequence ?? latestSequence + 1;

    if (sequence <= latestSequence)
    {
      throw new StorageError(
        "invalid_sequence",
        `sequence ${sequence} is not greater than latest ${latestSequence}`,
      );
    }

    const envelope = CreateChatEnvelope({
      ...input,
      pile,
      sessionId: validatedSessionId,
      sequence,
    });
    const entry: SessionLogEntry = {
      sequence,
      envelope,
    };

    await appendFile(historyPath, `${JSON.stringify(entry)}\n`, "utf8");

    try
    {
      await UpdateManifest(paths, pile, validatedSessionId, {
        lastSequence: sequence,
      });
    }
    catch (error)
    {
      if (!(error instanceof StorageError && error.code === "manifest_not_found"))
      {
        throw error;
      }
    }

    return envelope;
  });
}

export async function CollectSessionLogEntries(
  paths: StoragePaths,
  pile: string,
  sessionId: string,
): Promise<SessionLogEntry[]>
{
  const historyPath = ResolveHistoryFilePath(paths, pile, sessionId);
  const entries: SessionLogEntry[] = [];

  await StreamSessionLogEntries(historyPath, (entry) =>
  {
    entries.push(entry);
  });

  entries.sort((left, right) => left.sequence - right.sequence);
  return entries;
}

import { realpath } from "node:fs/promises";
import path from "node:path";

import { GetDefaultSheafChatPaths } from "../server/repo_paths.js";
import { StorageError } from "./errors.js";
import { ValidatePileName, ValidateSessionId } from "./validation.js";

export const x_pilesDirRelative = "data/sheaf-chat/sessions/piles";
export const x_historyFileSuffix = ".sheaf-history.jsonl";
export const x_manifestFileSuffix = ".manifest.json";
export const x_provisionalFileSuffix = ".provisional.json";
export const x_sessionFileSuffix = ".jsonl";

export interface StoragePaths
{
  repoRoot: string;
  dataDir: string;
  sessionsDir: string;
  pilesDir: string;
}

export function CreateStoragePaths(repoRoot: string): StoragePaths
{
  const defaults = GetDefaultSheafChatPaths(repoRoot);

  return {
    repoRoot,
    dataDir: defaults.dataDir,
    sessionsDir: defaults.sessionsDir,
    pilesDir: path.join(defaults.sessionsDir, "piles"),
  };
}

export function ResolvePileDirectory(paths: StoragePaths, pile: string): string
{
  const validatedPile = ValidatePileName(pile);
  return path.join(paths.pilesDir, validatedPile);
}

export function ResolveSessionStem(paths: StoragePaths, pile: string, sessionId: string): string
{
  const pileDir = ResolvePileDirectory(paths, pile);
  const validatedSessionId = ValidateSessionId(sessionId);
  return path.join(pileDir, validatedSessionId);
}

export function ResolveSessionFilePath(paths: StoragePaths, pile: string, sessionId: string): string
{
  const validatedSessionId = ValidateSessionId(sessionId);
  return `${ResolveSessionStem(paths, pile, sessionId)}${x_sessionFileSuffix}`;
}

export function ResolveManifestFilePath(paths: StoragePaths, pile: string, sessionId: string): string
{
  const validatedSessionId = ValidateSessionId(sessionId);
  return `${ResolveSessionStem(paths, pile, sessionId)}${x_manifestFileSuffix}`;
}

export function ResolveHistoryFilePath(paths: StoragePaths, pile: string, sessionId: string): string
{
  const validatedSessionId = ValidateSessionId(sessionId);
  return `${ResolveSessionStem(paths, pile, sessionId)}${x_historyFileSuffix}`;
}

export function ResolveProvisionalFilePath(paths: StoragePaths, pile: string, sessionId: string): string
{
  const validatedSessionId = ValidateSessionId(sessionId);
  return `${ResolveSessionStem(paths, pile, sessionId)}${x_provisionalFileSuffix}`;
}

export function ResolveRootDirectory(repoRoot: string, rootDirectory: string): string
{
  if (path.isAbsolute(rootDirectory))
  {
    return path.resolve(rootDirectory);
  }

  return path.resolve(repoRoot, rootDirectory);
}

export function ManifestSessionFileReference(
  repoRoot: string,
  pile: string,
  sessionId: string,
): string
{
  const validatedPile = ValidatePileName(pile);
  const validatedSessionId = ValidateSessionId(sessionId);
  return path.join(
    x_pilesDirRelative,
    validatedPile,
    `${validatedSessionId}${x_sessionFileSuffix}`,
  );
}

async function ResolveExistingPath(targetPath: string): Promise<string>
{
  const resolved = path.resolve(targetPath);

  try
  {
    return await realpath(resolved);
  }
  catch (error)
  {
    const nodeError = error as NodeJS.ErrnoException;

    if (nodeError.code !== "ENOENT")
    {
      throw error;
    }
  }

  return resolved;
}

export async function AssertPathWithinRoot(
  candidatePath: string,
  rootPath: string,
): Promise<string>
{
  const resolvedRoot = await ResolveExistingPath(rootPath);
  const resolvedCandidate = await ResolveExistingPath(candidatePath);
  const relative = path.relative(resolvedRoot, resolvedCandidate);

  if (relative === "" || (!relative.startsWith("..") && !path.isAbsolute(relative)))
  {
    return resolvedCandidate;
  }

  throw new StorageError("path_escape", "path escapes the storage root");
}

export async function AssertPilePathWithinRoot(
  paths: StoragePaths,
  pileDirectory: string,
): Promise<string>
{
  return AssertPathWithinRoot(pileDirectory, paths.pilesDir);
}

