  return { provider: model.provider, id: model.id };
}

async function CreateTestManager(
  repoRoot: string,
  options: {
    fakeSessions?: Map<string, FakePiSession>;
    summarizer?: (text: string) => Promise<{ chatName: string; description: string }>;
