{
  await WithFakeRepoAsync(async (repoRoot) =>
  {
    const fakeSessions = new Map<string, FakePiSession>();
    const manager = await CreateTestManager(repoRoot, { fakeSessions });
    const storagePaths = CreateStorage(repoRoot);
