export interface FakeTimerController
{
  setTimeout: typeof setTimeout;
  clearTimeout: typeof clearTimeout;
  RunDueTimers(): void;
}

export function CreateFakeTimers(): FakeTimerController
{
  const pending = new Map<NodeJS.Timeout, { callback: () => void; dueAt: number }>();
  let now = 0;
  let nextId = 1;

  const setTimeoutFn = ((callback: () => void, delay?: number) =>
  {
    const id = nextId++ as unknown as NodeJS.Timeout;
    pending.set(id, {
      callback,
      dueAt: now + (delay ?? 0),
    });
    return id;
  }) as typeof setTimeout;

  const clearTimeoutFn = ((id: NodeJS.Timeout) =>
  {
    pending.delete(id);
  }) as typeof clearTimeout;

  return {
    setTimeout: setTimeoutFn,
    clearTimeout: clearTimeoutFn,
    RunDueTimers()
    {
      const due = [...pending.entries()].filter(([, entry]) => entry.dueAt <= now);
      for (const [id, entry] of due)
      {
        pending.delete(id);
        entry.callback();
      }
    },
  };
}

export function AdvanceFakeTimers(controller: FakeTimerController, ms: number): void
{
  const internal = controller as FakeTimerController & { now?: number };

  if (internal.now === undefined)
  {
    Object.defineProperty(controller, "now", { value: 0, writable: true });
  }

  (controller as { now: number }).now += ms;
  controller.RunDueTimers();
}

